-- FND-003 Core schema: identity, workspaces, members, departments, invites, audit log.
-- Design: docs/architecture/DATABASE.md §2 and docs/architecture/MULTI_TENANCY.md.
-- IDs are UUID v7 generated by the API; gen_random_uuid() is only a fallback default.

-- ---------------------------------------------------------------------------
-- Access defaults (ADR-006): the public Supabase keys (anon, authenticated) get
-- nothing in the public schema, now or for tables added by later migrations.
-- The API connects as fasthyr_api, which gets table privileges automatically.
-- ---------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'fasthyr_api') then
    -- NOLOGIN here; each environment turns on login with its own password (see DEPLOYMENT.md).
    create role fasthyr_api nologin bypassrls;
  end if;
end
$$;

grant usage on schema public to fasthyr_api;

alter default privileges for role postgres in schema public
  revoke all on tables from anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all on sequences from anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all on functions from anon, authenticated, public;
alter default privileges for role postgres in schema public
  grant select, insert, update, delete on tables to fasthyr_api;
alter default privileges for role postgres in schema public
  grant usage, select on sequences to fasthyr_api;

-- Keeps updated_at current on tables that have it.
create function public.set_updated_at() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Identity and workspaces
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text,
  avatar_url text,
  last_workspace_id uuid,
  created_at timestamptz not null default now()
);

create table public.workspaces (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 120),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 63),
  owner_id uuid not null references public.profiles (id),
  timezone text not null default 'UTC',
  stripe_customer_id text unique,
  trial_granted_at timestamptz,
  created_at timestamptz not null default now()
);

alter table public.profiles
  add constraint profiles_last_workspace_id_fkey
  foreign key (last_workspace_id) references public.workspaces (id) on delete set null;

create table public.company_profiles (
  workspace_id uuid primary key references public.workspaces (id),
  company_name text not null,
  logo_path text,
  banner_path text,
  website text,
  industry text,
  company_size text,
  hq_country text,
  timezone text,
  about text check (length(about) <= 600),
  careers_url text,
  updated_by uuid references public.profiles (id),
  updated_at timestamptz not null default now()
);

create trigger company_profiles_set_updated_at
  before update on public.company_profiles
  for each row execute function public.set_updated_at();

create table public.departments (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id),
  name text not null check (
    length(btrim(name)) between 1 and 80 and lower(btrim(name)) <> 'no department'
  ),
  description text,
  created_at timestamptz not null default now(),
  constraint departments_workspace_id_id_key unique (workspace_id, id)
);

create unique index departments_workspace_id_name_key
  on public.departments (workspace_id, lower(name));

create table public.workspace_members (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id),
  user_id uuid not null references public.profiles (id),
  role text not null check (role in ('admin', 'recruiter', 'hiring_manager')),
  is_owner boolean not null default false,
  status text not null default 'active' check (status in ('active', 'removed')),
  last_active_at timestamptz,
  created_at timestamptz not null default now(),
  constraint workspace_members_workspace_id_user_id_key unique (workspace_id, user_id),
  constraint workspace_members_workspace_id_id_key unique (workspace_id, id),
  constraint workspace_members_owner_is_admin check (not is_owner or role = 'admin')
);

create index workspace_members_user_id_idx on public.workspace_members (user_id);
create unique index workspace_members_one_owner_idx
  on public.workspace_members (workspace_id) where is_owner;

create table public.member_departments (
  workspace_id uuid not null references public.workspaces (id),
  member_id uuid not null,
  department_id uuid not null,
  primary key (member_id, department_id),
  constraint member_departments_member_fkey foreign key (workspace_id, member_id)
    references public.workspace_members (workspace_id, id) on delete cascade,
  constraint member_departments_department_fkey foreign key (workspace_id, department_id)
    references public.departments (workspace_id, id) on delete cascade
);

create index member_departments_department_id_idx on public.member_departments (department_id);

create table public.invites (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id),
  email text not null check (email = lower(email)),
  role text not null check (role in ('admin', 'recruiter', 'hiring_manager')),
  -- Departments to assign on accept. An array cannot carry FKs: the department service
  -- removes a deleted department's ID from pending invites.
  department_ids uuid[] not null default '{}',
  code text not null unique,
  token_hash text not null unique,
  invited_by uuid not null references public.profiles (id),
  status text not null default 'pending'
    check (status in ('pending', 'accepted', 'revoked', 'expired')),
  expires_at timestamptz not null default (now() + interval '7 days'),
  accepted_by uuid references public.profiles (id),
  created_at timestamptz not null default now()
);

-- Resending an invite rotates the code and token on the same row.
create unique index invites_one_pending_per_email_idx
  on public.invites (workspace_id, email) where status = 'pending';

-- ---------------------------------------------------------------------------
-- Audit log (append-only)
-- ---------------------------------------------------------------------------
create table public.audit_log (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id),
  -- No FK: the log must never change when a user is deleted. Null for system actions.
  actor_id uuid,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index audit_log_workspace_id_created_at_idx on public.audit_log (workspace_id, created_at);

create function public.reject_audit_log_change() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'audit_log is append-only';
end;
$$;

create trigger audit_log_append_only
  before update or delete on public.audit_log
  for each row execute function public.reject_audit_log_change();

create trigger audit_log_no_truncate
  before truncate on public.audit_log
  for each statement execute function public.reject_audit_log_change();

revoke update, delete, truncate on public.audit_log from fasthyr_api;

-- ---------------------------------------------------------------------------
-- New auth user → profile row
-- ---------------------------------------------------------------------------
create function public.handle_new_user() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, full_name, avatar_url)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    coalesce(new.raw_user_meta_data ->> 'avatar_url', new.raw_user_meta_data ->> 'picture')
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Lockdown: RLS on with no policies; no privileges for the public keys.
-- ---------------------------------------------------------------------------
alter table public.profiles enable row level security;
alter table public.workspaces enable row level security;
alter table public.company_profiles enable row level security;
alter table public.departments enable row level security;
alter table public.workspace_members enable row level security;
alter table public.member_departments enable row level security;
alter table public.invites enable row level security;
alter table public.audit_log enable row level security;

revoke all on all tables in schema public from anon, authenticated;
revoke all on all functions in schema public from anon, authenticated, public;
